                        },
                        new
                        {
                            Id = new Guid("5a1e0000-0000-4000-8000-000000000002"),
                            HtmlBody = "<div style=\"font-family:sans-serif;max-width:480px;margin:0 auto;color:#111;\">\n  <h2>e-kariyerim password reset</h2>\n  <p>We received a request to reset your account's password. Click the button below to set a new password. This link will expire in 30 minutes.</p>\n  <p>\n    <a href=\"{{ResetLink}}\" style=\"display:inline-block;padding:10px 20px;background:#2563eb;color:#fff;text-decoration:none;border-radius:6px;\">\n      Reset my password\n    </a>\n  </p>\n  <p style=\"color:#555;font-size:13px;\">If you didn't request this, you can safely ignore this email — no changes will be made to your account.</p>\n</div>",
                            Key = "PasswordReset",
                            Locale = "en",
                            Subject = "e-kariyerim password reset"
                        },
                        new
                        {
                            Id = new Guid("5a1e0000-0000-4000-8000-000000000003"),
                            HtmlBody = "<div style=\"font-family:sans-serif;max-width:480px;margin:0 auto;color:#111;\">\n  <h2>e-kariyerim şifreniz değiştirildi</h2>\n  <p>e-kariyerim hesabınızın şifresi az önce değiştirildi ve diğer tüm cihazlardaki oturumlarınız güvenlik amacıyla sonlandırıldı.</p>\n  <p style=\"color:#555;font-size:13px;\">Bu işlemi siz yapmadıysanız lütfen hemen bizimle iletişime geçin.</p>\n</div>",
